CREATE TABLE IF NOT EXISTS gst_settlement_runs(settlement_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, organization_id TEXT NOT NULL, entity_id TEXT, liability NUMERIC NOT NULL DEFAULT 0, challan_amount NUMERIC NOT NULL DEFAULT 0, ledger_amount NUMERIC NOT NULL DEFAULT 0, bank_amount NUMERIC NOT NULL DEFAULT 0, difference NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'DRAFT', exception_reason TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(filing_id));
CREATE TABLE IF NOT EXISTS gst_settlement_matches(match_id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, amount NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'MATCHED', notes TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(settlement_id,source_type,source_id));
CREATE TABLE IF NOT EXISTS gst_settlement_signoffs(signoff_id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', signed_by TEXT, signed_at TIMESTAMP, remarks TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(settlement_id));
